struct audio_cal_callbacks {
	int (*alloc)(int32_t, size_t, void *);
	int (*dealloc)(int32_t, size_t, void *);
	int (*pre_cal)(int32_t, size_t, void *);
	int (*set_cal)(int32_t, size_t, void *);
	int (*get_cal)(int32_t, size_t, void *);
	int (*post_cal)(int32_t, size_t, void *);
};

struct audio_cal_type_header {
	__s32 version;
	__s32 buffer_number;
};

struct audio_cal_data {
	__s32 cal_size;
	__s32 mem_handle;
	__u32 cma_mem;
};

struct audio_cal_type_dealloc {
	struct audio_cal_type_header cal_hdr;
	struct audio_cal_data cal_data;
};

struct audio_cal_info {
	struct mutex common_lock;
	struct mutex cal_mutex[52];
	struct list_head client_info[52];
	int ref_count;
};

